import{_ as i,l as o,o as e,c as l,v as n,p as s,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"指数纳入与被动流","description":"","frontmatter":{"title":"指数纳入与被动流","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/index-inclusion-passive-flow.md","filePath":"quant/index-inclusion-passive-flow.md","lastUpdated":1789023840000}'),p={name:"quant/index-inclusion-passive-flow.md"};function B(c,a,u,_,f,m){const t=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="指数纳入与被动流" tabindex="-1">指数纳入与被动流 <a class="header-anchor" href="#指数纳入与被动流" aria-label="Permalink to &quot;指数纳入与被动流&quot;">​</a></h1><div class="epigraph"><p>被动资金必须在规则指定的时点买进新成分、卖出旧成分；价格压力来自向下倾斜的需求曲线，不是来自对新基本面的发现。</p><footer>—— Shleifer, Do Demand Curves for Stocks Slope Down?, Journal of Finance, 1986；调仓执行见 Chen, Noronha and Singal 与指数调仓课</footer></div><p><a href="/quant/earnings-season-strategies">上一课</a>的催化剂是公司公告。指数纳入的缺口是<strong>机械、预先公告的被动需求</strong>。主干 <a href="/quant/index-rebalance-arb">指数调仓套利</a> 已写宣布日–生效日的冲击与跟踪误差权衡。本课放策略地图：纳入溢价、删出折价、ETF 申赎流，以及它们如何污染动量与价值因子——不要把需求冲击写成新的风险溢价再对 <a href="/quant/capm">CAPM</a> 回归一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shleifer、Harris–Gurel 用标普纳入当作需求曲线实验：消息几乎无信息，价格仍动。其后 ETF 把被动流变成每日创造赎回，Ben-David、Franzoni、Moussawi 等讨论波动与非基本面交易。问题是策略定义：吃纳入的人在和指数产品抢流动性，容量随被动份额上升先变好后变差（更多流量，也更多同类套利）。与事件驱动：完成风险低（规则几乎确定），但生效日拍卖的缺口风险高。</p><p>因子污染：调入名单偏大盘、偏动量、偏流动性。静态价值/动量若在调仓周异常，先减掉被动流再谈 alpha。</p><h3 id="永久需求与临时冲击" tabindex="-1">永久需求与临时冲击 <a class="header-anchor" href="#永久需求与临时冲击" aria-label="Permalink to &quot;永久需求与临时冲击&quot;">​</a></h3><p>若指数基金会长期持有，纳入后价格不必完全回吐。若杠杆账户只在窗口内做市，生效日后会回吐。产品宣传常把历史「纳入溢价」当永续 alpha；被动份额与抢跑程度已经改写了这笔租金。</p><p><span class="marginnote">跟踪误差约束迫使指数基金在生效日集中成交。套利者若更早完成，赚的是 TE 预算换来的流动性补偿，见后课基准与跟踪误差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件：纳入、删出、权重再平衡、ETF 篮子申赎。信号只用公开规则与预告名单。执行：相对拍卖、相对 VWAP 的实施缺口单独记账。风险：在篮子里做多调入、做空调出时的残差行业与动量。容量：与 ETF 资产管理规模同期估计，不用 1990 年代纳入溢价外推。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编制规则把市值与流动性映射成必须成交的 \\(\\Delta w\\)。灵活资本提供流动性，收取冲击补偿。被动份额越高，机械流越大，因子与 ARP 的再平衡也越同步——拥挤与被动流是同一管道的两端。</p>',13)),(e(),s(h,null,{default:r(()=>[E(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Rule%5B%22%E7%BC%96%E5%88%B6%E8%A7%84%E5%88%99%22%5D%20--%3E%20Dw%5B%22%E5%BF%85%E9%A1%BB%E6%88%90%E4%BA%A4%E7%9A%84%E6%9D%83%E9%87%8D%E5%B7%AE%22%5D%0A%20%20ETF%5B%22ETF%20%E7%94%B3%E8%B5%8E%22%5D%20--%3E%20Dw%0A%20%20Dw%20--%3E%20Px%5B%22%E9%9C%80%E6%B1%82%E6%9B%B2%E7%BA%BF%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20Arb%5B%22%E7%81%B5%E6%B4%BB%E8%B5%84%E6%9C%AC%22%5D%20--%3E%20Px%0A%20%20Px%20--%3E%20Fac%5B%22%E6%B1%A1%E6%9F%93%E5%8A%A8%E9%87%8F%E4%B8%8E%E4%BB%B7%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写刺探未公开审核名单。自定义指数与智能 beta 的规则若可复制，同样适用，并更快拥挤。中国指数与 T+1 约束见中国课，不要照搬标普拍卖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纳入与被动流是机械需求，不是基本面发现。</li><li>租金随被动份额与抢跑改变，不可用早期样本当产品。</li><li>先从因子收益里减掉调仓周，再谈溢价。</li><li>出处：Shleifer, <em>JF</em>, 1986；Chen, Noronha and Singal, <em>JF</em>, 2004；执行细节见指数调仓课。</li></ul>',4))])}const q=i(p,[["render",B]]);export{T as __pageData,q as default};
